"""Regenerates tests/fixtures/core_contract.json from the CURRENT rule engine.

Run it only when a change to the rules is intentional (agreed with the course line):

    python tests/fixtures/make_core_contract.py

then review `git diff tests/fixtures/core_contract.json` before committing. The profiles are
synthetic and hand-written, one or two per group; the expected values are whatever the engine
says today, so the file records the engine's behaviour, it does not assert clinical truth.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from core_contract_profiles import PROFILES, build_profile  # noqa: E402

from para_triage.rules import RuleEngine, Status  # noqa: E402

OUT = Path(__file__).with_name("core_contract.json")


def build() -> dict:
    engine = RuleEngine()
    cases = []
    for name, group, raw in PROFILES:
        result = engine.evaluate(build_profile(raw))
        cases.append(
            {
                "name": name,
                "group": group,
                "profile": raw,
                "primary_class": result.primary_class,
                "meets": result.meets,
                "statuses": {
                    str(cid): v.status.value
                    for cid, v in result.verdicts.items()
                    if v.status is not Status.NOT_APPLICABLE
                },
            }
        )
    return {
        "note": "Generated by tests/fixtures/make_core_contract.py from the rule engine. Synthetic profiles only.",
        "cases": cases,
    }


if __name__ == "__main__":
    OUT.write_text(json.dumps(build(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"wrote {OUT} ({len(PROFILES)} profiles)")
